/**
 * Compares query-level initial bindings with the SPARQL VALUES transport used when a caller must serialize them.
 */
class MemoryInitialBindingBindingParityTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI P = VF.createIRI("urn:p");
	private static final IRI Q = VF.createIRI("urn:q");
	private static final IRI TERM = VF.createIRI("urn:term");
	private Repository repository;

	@BeforeEach
	void setUp() {
		repository = new SailRepository(new MemoryStore());
		repository.init();
		try (RepositoryConnection connection = repository.getConnection()) {
			IRI subject = VF.createIRI("urn:s");
			IRI otherSubject = VF.createIRI("urn:other");
			connection.add(subject, P, VF.createIRI("urn:object"));
			connection.add(otherSubject, P, VF.createIRI("urn:other-object"));
			connection.add(subject, Q, VF.createBNode("minus-input"));
			connection.add(otherSubject, Q, VF.createBNode("other-value"));

			TripleTerm object = VF.createTripleTerm(VF.createIRI("urn:inner-subject"),
					VF.createIRI("urn:inner-predicate"), VF.createBNode("nested-object-bnode"));
			TripleTerm nested = VF.createTripleTerm(VF.createIRI("urn:outer-subject"),
					VF.createIRI("urn:outer-predicate"), object);
			connection.add(VF.createIRI("urn:triple-subject"), TERM, nested);
		}
	}

	@AfterEach
	void tearDown() {
		repository.shutDown();
	}

	@Test
	void minusRhsOnlyBindingRequiresExplicitUnsupportedTransport() {
		String query = "SELECT ?s WHERE { ?s <urn:p> ?o MINUS { ?r <urn:q> ?rhs } }";
		assertUnsupportedTransport("MINUS RHS-only variable", query, "rhs", VF.createBNode("minus-input"),
				bag(binding("s", VF.createIRI("urn:s")), binding("s", VF.createIRI("urn:other"))), "MINUS");
	}

	@Test
	void nestedGroupFilterRequiresExplicitUnsupportedTransport() {
		String query = "SELECT ?s WHERE { { ?s <urn:p> ?o FILTER(?required = <urn:filter>) } }";
		assertUnsupportedTransport("nested group FILTER", query, "required", VF.createIRI("urn:filter"),
				bag(binding("s", VF.createIRI("urn:s")), binding("s", VF.createIRI("urn:other"))), "nested FILTER");
	}

	@Test
	void existsReceivesTheSameInitialMapping() {
		assertParity("EXISTS", "SELECT ?s WHERE { ?s <urn:p> ?o FILTER EXISTS { ?s <urn:q> ?required } }",
				"required", VF.createBNode("minus-input"));
	}

	@Test
	void notExistsReceivesTheSameInitialMapping() {
		assertParity("NOT EXISTS", "SELECT ?s WHERE { ?s <urn:p> ?o FILTER NOT EXISTS { ?s <urn:q> ?required } }",
				"required", VF.createBNode("absent-value"));
	}

	@Test
	void optionalMissingSubjectRequiresExplicitUnsupportedTransport() {
		String query = "SELECT ?s ?o WHERE { OPTIONAL { ?s <urn:p> ?o } }";
		assertUnsupportedTransport("OPTIONAL", query, "s", VF.createBNode("optional-missing"),
				bag(new MapBindingSet()), "OPTIONAL");
	}

	@Test
	void unionReceivesTheSameInitialMappingInBothBranches() {
		assertParity("UNION", "SELECT ?s ?o WHERE { { ?s <urn:p> ?o } UNION { ?s <urn:q> ?o } }", "s",
				VF.createIRI("urn:s"));
	}

	@Test
	void groupingAndModifiersRequireExplicitUnsupportedTransport() {
		String query = "SELECT ?group (COUNT(?o) AS ?count) WHERE { ?s <urn:p> ?o } "
				+ "GROUP BY ?group ORDER BY ?group LIMIT 1 OFFSET 0";
		assertUnsupportedTransport("GROUP BY/ORDER BY/LIMIT/OFFSET", query, "group", VF.createLiteral("group-key"),
				bag(binding("count", VF.createLiteral("2", VF.createIRI("http://www.w3.org/2001/XMLSchema#integer")))),
				"GROUP BY");
	}

	@Test
	void blankNodesInsideObjectTripleTermsSurviveTheTransport() {
		TripleTerm object = VF.createTripleTerm(VF.createIRI("urn:inner-subject"),
				VF.createIRI("urn:inner-predicate"), VF.createBNode("nested-object-bnode"));
		TripleTerm nested = VF.createTripleTerm(VF.createIRI("urn:outer-subject"),
				VF.createIRI("urn:outer-predicate"), object);
		assertParity("nested TripleTerm with BNode component",
				"SELECT ?s WHERE { ?s <urn:term> ?triple FILTER(?triple = ?bound) }", "bound", nested);
	}

	private void assertParity(String shape, String query, String bindingName, Value value) {
		try (RepositoryConnection connection = repository.getConnection()) {
			MapBindingSet input = new MapBindingSet(1);
			input.addBinding(bindingName, value);
			List<BindingSet> nativeRows = evaluate(connection, query, input);
			List<BindingSet> serializedRows = evaluate(connection, SPARQLQueries.withInitialBindings(query, input),
					null);

			assertFalse(nativeRows.isEmpty(), shape + " must exercise a non-empty native result");
			assertEquals(bag(nativeRows), bag(serializedRows),
					shape + " must match the result bag from Query.setBinding");
		}
	}

	private void assertUnsupportedTransport(String shape, String query, String bindingName, Value value,
			Map<Map<String, Value>, Integer> expectedNativeBag, String scopeReason) {
		try (RepositoryConnection connection = repository.getConnection()) {
			MapBindingSet input = new MapBindingSet(1);
			input.addBinding(bindingName, value);
			List<BindingSet> nativeRows = evaluate(connection, query, input);
			assertEquals(expectedNativeBag, bag(nativeRows),
					shape + " native result bag is part of the transport contract");

			UnsupportedOperationException unsupported = assertThrows(UnsupportedOperationException.class,
					() -> SPARQLQueries.withInitialBindings(query, input),
					shape + " must be rejected when VALUES cannot preserve initial-binding semantics");
			assertTrue(unsupported.getMessage().contains(scopeReason),
					shape + " rejection must identify the unsupported scope: " + unsupported.getMessage());
		}
	}

	private static List<BindingSet> evaluate(RepositoryConnection connection, String query, BindingSet bindings) {
		TupleQuery tupleQuery = connection.prepareTupleQuery(query);
		if (bindings != null) {
			bindings.forEach(binding -> tupleQuery.setBinding(binding.getName(), binding.getValue()));
		}
		List<BindingSet> rows = new ArrayList<>();
		try (TupleQueryResult result = tupleQuery.evaluate()) {
			while (result.hasNext()) {
				rows.add(result.next());
			}
		}
		return rows;
	}

	private static Map<Map<String, Value>, Integer> bag(List<BindingSet> rows) {
		Map<Map<String, Value>, Integer> result = new HashMap<>();
		for (BindingSet row : rows) {
			Map<String, Value> values = new TreeMap<>();
			row.forEach(binding -> values.put(binding.getName(), binding.getValue()));
			result.merge(values, 1, Integer::sum);
		}
		return result;
	}

	private static Map<Map<String, Value>, Integer> bag(BindingSet... rows) {
		return bag(List.of(rows));
	}

	private static BindingSet binding(String name, Value value) {
		MapBindingSet row = new MapBindingSet(1);
		row.addBinding(name, value);
		return row;
	}
}
